import base64,hashlib,json,pathlib
b=base64.b64decode('')
expected='a4a96e4fd4c917b47e305a317095e4a9538d243e8f3091a9a91ccc611a42067e'
assert hashlib.sha256(b).hexdigest()==expected
d=pathlib.Path('/var/tmp/km3-pmp4010-accept-20261019-a4a96e4f')
d.mkdir(mode=0o700,exist_ok=False)
p=d/'controlled-forward.runner.py'
with p.open('xb') as f:f.write(b)
p.chmod(0o600)
actual=hashlib.sha256(p.read_bytes()).hexdigest()
assert actual==expected
print(json.dumps(dict(path=str(p),bytes=p.stat().st_size,sha256=actual,verified=True,CAN_socket_opens=0,CAN_sends=0,process_control=0)))
